<div id="page-content" class="page-wrapper clearfix"><div class="card"><div class="page-title clearfix"><h1><?php echo app_lang('engenharia_dashboard'); ?></h1><div class="title-button-group"><a class="btn btn-primary" href="<?php echo get_uri('engenharia/laudos'); ?>"><i data-feather="file-text" class="icon-16"></i> <?php echo app_lang('engenharia_laudos'); ?></a></div></div><div class="card-body"><div class="row g-3 mb20"><div class="col-md-3 col-sm-6"><div class="card bg-primary text-white"><div class="card-body"><h6><?php echo app_lang('engenharia_total_laudos'); ?></h6><h2><?php echo (int)($stats->total??0); ?></h2></div></div></div><div class="col-md-3 col-sm-6"><div class="card bg-info text-white"><div class="card-body"><h6><?php echo app_lang('engenharia_scheduled_inspections'); ?></h6><h2><?php echo (int)$scheduled; ?></h2></div></div></div><div class="col-md-3 col-sm-6"><div class="card bg-warning text-dark"><div class="card-body"><h6><?php echo app_lang('engenharia_in_review'); ?></h6><h2><?php echo (int)($stats->review??0); ?></h2></div></div></div><div class="col-md-3 col-sm-6"><div class="card bg-secondary text-white"><div class="card-body"><h6><?php echo app_lang('engenharia_awaiting_info'); ?></h6><h2><?php echo (int)($stats->awaiting_information??0); ?></h2></div></div></div></div><div class="row g-3"><div class="col-lg-6"><div class="card"><div class="card-header"><h5 class="mb0"><?php echo app_lang('engenharia_status_summary'); ?></h5></div><div class="card-body"><?php foreach(array('draft'=>'engenharia_status_draft','scheduled'=>'engenharia_status_scheduled','inspection'=>'engenharia_status_inspection','awaiting_information'=>'engenharia_status_awaiting_information','review'=>'engenharia_status_review','finalized'=>'engenharia_status_finalized','canceled'=>'engenharia_status_canceled') as $code=>$label){$value=(int)($stats->{$code}??0);$total=max(1,(int)($stats->total??0)); ?><div class="mb10"><div class="clearfix"><span><?php echo app_lang($label); ?></span><strong class="float-end"><?php echo $value; ?></strong></div><div class="progress"><div class="progress-bar" style="width:<?php echo round($value/$total*100); ?>%"></div></div></div><?php } ?></div></div></div><div class="col-lg-6"><div class="card"><div class="card-header"><h5 class="mb0"><?php echo app_lang('engenharia_nc_by_criticality'); ?></h5></div><div class="card-body"><?php foreach(array('low'=>'Baixa','medium'=>'Média','high'=>'Alta','critical'=>'Crítica') as $code=>$label){ ?><div class="d-flex justify-content-between border-bottom py10"><span><?php echo $label; ?></span><span class="badge <?php echo $code==='critical'?'bg-danger':($code==='high'?'bg-warning text-dark':'bg-secondary'); ?>"><?php echo (int)$nc_summary[$code]; ?></span></div><?php } ?><div class="mt15"><span class="badge bg-danger"><?php echo app_lang('engenharia_calibration_expired'); ?>: <?php echo (int)$instruments_expired; ?></span> <span class="badge bg-warning text-dark"><?php echo app_lang('engenharia_calibration_soon'); ?>: <?php echo (int)$instruments_soon; ?></span></div></div></div></div></div><div class="col-12"><div class="card"><div class="card-header"><h5 class="mb0"><?php echo app_lang('engenharia_recent_laudos'); ?></h5></div><div class="table-responsive"><table class="table table-hover mb0"><thead><tr><th><?php echo app_lang('engenharia_laudo_number'); ?></th><th><?php echo app_lang('title'); ?></th><th><?php echo app_lang('client'); ?></th><th><?php echo app_lang('status'); ?></th><th><?php echo app_lang('engenharia_last_update'); ?></th></tr></thead><tbody><?php foreach($recent as $row){ ?><tr><td><a href="<?php echo get_uri('engenharia/laudos/view/'.$row->id); ?>"><?php echo esc($row->number); ?></a></td><td><?php echo esc($row->title); ?></td><td><?php echo esc($row->client_name); ?></td><td><?php echo engenharia_status_badge($row->status); ?></td><td><?php echo esc($row->updated_at); ?></td></tr><?php } ?></tbody></table></div></div></div></div></div></div>
